template:
use std::cell::RefCell;
use std::rc::Rc;

type SharedVec = Rc<RefCell<Vec<i32>>>;

fn append(list: &SharedVec, val: i32) {
    list.⟦slot1⟧().⟦slot2⟧(val);
}

fn main() {
    let list =
        Rc::new(RefCell::new(vec![1]));
    let copy = Rc::clone(&list);
    append(&list, 2);
    println!("{:?}", copy.borrow());
}

tests:
#[test]
fn appends_to_shared() {
    let list = Rc::new(RefCell::new(vec![10]));
    let alias = Rc::clone(&list);
    append(&list, 20);
    assert_eq!(*alias.borrow(), vec![10, 20]);
}
